import { useEffect, useState } from 'react';
import { useAuth } from './hooks/useAuth';
import { Routes, Route, useNavigate, Navigate, useLocation } from 'react-router-dom';
import HomePage from './pages/HomePage';
import BarbershopPage from './pages/BarbershopPage';
import BookingPage from './pages/BookingPage';
import AppointmentsPage from './pages/AppointmentsPage';
import LoginPage from './pages/LoginPage';
import ForgotPasswordPage from './pages/ForgotPasswordPage';
import ResetPasswordPage from './pages/ResetPasswordPage';
import CompanyPage from './pages/CompanyPage';
import ShopDayView from './pages/ShopDayView';
import './App.css';

function RequireAuth({ children }) {
  const { user } = useAuth();
  if (!user) return <Navigate to="/login" replace />;
  return children;
}

function RequireCompany({ children }) {
  const { user, isCompany } = useAuth();
  if (!user) return <Navigate to="/login" replace />;
  if (!isCompany) return <Navigate to="/" replace />;
  return children;
}

export default function App() {
  const { user, isCompany } = useAuth();
  const navigateRouter = useNavigate();
  const location = useLocation();
  const [resetToken, setResetToken] = useState('');
  const [theme, setTheme] = useState(() => localStorage.getItem('lebux_theme') || 'dark');
  const isAutoPinkTheme = !isCompany && user?.gender === 'feminino';

  const navigate = (to, data = {}) => {
    const state = {
      shop: data.shop,
      shopId: data.shopId,
      service: data.service,
      token: data.token,
    };

    switch (to) {
      case 'home': return navigateRouter('/', { state });
      case 'barbershop': return navigateRouter('/barbershop', { state });
      case 'booking': return navigateRouter('/booking', { state });
      case 'appointments': return navigateRouter('/appointments', { state });
      case 'company': return navigateRouter('/company', { state });
      case 'shop-day': return navigateRouter(`/shop-day/${data.shopId || ''}`, { state });
      case 'login': return navigateRouter('/login', { state });
      case 'forgot-password': return navigateRouter('/forgot-password', { state });
      case 'reset-password': return navigateRouter('/reset-password', { state });
      default: return navigateRouter('/', { state });
    }
  };

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const token = params.get('token');
    if (token) {
      setResetToken(token);
      navigateRouter('/reset-password');
    }
  }, [navigateRouter]);

  useEffect(() => {
    document.documentElement.classList.toggle('theme-light', theme === 'light');
    document.documentElement.classList.toggle('theme-pink', theme === 'pink');
    localStorage.setItem('lebux_theme', theme);
  }, [theme]);

  useEffect(() => {
    if (isAutoPinkTheme) {
      setTheme('pink');
      return;
    }
    if (!['light', 'pink'].includes(theme)) {
      setTheme('dark');
    }
  }, [isAutoPinkTheme]);

  const toggleTheme = () => {
    setTheme((current) => {
      if (current === 'dark') return 'light';
      if (current === 'light') return 'pink';
      return 'dark';
    });
  };

  return (
    <div className="app-shell">
      <button className="theme-toggle-btn" onClick={toggleTheme} title={theme === 'dark' ? 'Mudar para tema claro' : theme === 'light' ? 'Mudar para tema rosa' : 'Voltar ao tema escuro'}>
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>
          <span>{theme === 'dark' ? '🌙' : theme === 'light' ? '☀️' : '🌸'}</span>
          <span style={{ fontSize: 12, fontWeight: 700 }}>{theme === 'dark' ? 'Escuro' : theme === 'light' ? 'Claro' : 'Rosa'}</span>
        </span>
      </button>
      <Routes>
        <Route path="/" element={<RequireAuth><HomePage navigate={navigate} /></RequireAuth>} />
        <Route path="/barbershop" element={<RequireAuth><BarbershopPage navigate={navigate} /></RequireAuth>} />
        <Route path="/booking" element={<RequireAuth><BookingPage navigate={navigate} /></RequireAuth>} />
        <Route path="/appointments" element={<RequireAuth><AppointmentsPage navigate={navigate} /></RequireAuth>} />
        <Route path="/login" element={<LoginPage navigate={navigate} />} />
        <Route path="/forgot-password" element={<ForgotPasswordPage navigate={navigate} />} />
        <Route path="/reset-password" element={<ResetPasswordPage navigate={navigate} token={resetToken} />} />
        <Route path="/company" element={<RequireCompany><CompanyPage navigate={navigate} /></RequireCompany>} />
        <Route path="/shop-day/:shopId?" element={<RequireCompany><ShopDayView navigate={navigate} /></RequireCompany>} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>

      {(() => {
        const hideOn = ['/login', '/forgot-password', '/reset-password'];
        const hideNav = hideOn.includes(location.pathname);
        if (hideNav) return null;
        return (
          <nav className="bottom-nav">
            {user ? (
              <>
                {isCompany ? (
                  <button className={`nav-btn`} onClick={() => navigate('company')}>
                    <span className="nav-icon">💼</span>
                    <span className="nav-label">Empresa</span>
                  </button>
                ) : (
                  <button className={`nav-btn`} onClick={() => navigate('home')}>
                    <span className="nav-icon">🏠</span>
                    <span className="nav-label">Início</span>
                  </button>
                )}
                <button className={`nav-btn`} onClick={() => navigate('appointments')}>
                  <span className="nav-icon">📅</span>
                  <span className="nav-label">Agendados</span>
                </button>
                <button className={`nav-btn`} onClick={() => navigate('login')}>
                  <span className="nav-icon">👤</span>
                  <span className="nav-label">Perfil</span>
                </button>
              </>
            ) : (
              <button className={`nav-btn`} onClick={() => navigate('login')}>
                <span className="nav-icon">👤</span>
                <span className="nav-label">Entrar</span>
              </button>
            )}
          </nav>
        );
      })()}
    </div>
  );
}
